import json,re
P=[
("Soil erosion and agricultural sustainability","D. R. Montgomery",2007,"PNAS","10.1073/pnas.0611508104","Soil erosion","Free to read","PNAS open archive",False,"https://www.pnas.org/doi/pdf/10.1073/pnas.0611508104","Conventional ploughing erodes soil 10–100× faster than it forms; no-till and conservation farming can close the gap."),
("Soil carbon sequestration impacts on global climate change and food security","R. Lal",2004,"Science","10.1126/science.1097396","Soil carbon","Subscription","©",False,None,"Restoring degraded soils could store large amounts of carbon while raising crop yields."),
("Global consequences of land use","J. A. Foley et al.",2005,"Science","10.1126/science.1111772","Land use","Subscription","©",False,None,"Croplands and pastures now rival forests as Earth's largest land cover, trading short-term needs against long-term ecosystem services."),
("Solutions for a cultivated planet","J. A. Foley et al.",2011,"Nature","10.1038/nature10452","Food security","Subscription","©",False,None,"Halting farmland expansion, closing yield gaps, using water and fertiliser better, shifting diets and cutting waste could double food supply sustainably."),
("High-resolution global maps of 21st-century forest cover change","M. C. Hansen et al.",2013,"Science","10.1126/science.1244693","Forests","Subscription","©",False,None,"Landsat mapping showed 2.3 million km² of forest lost and 0.8 million km² gained in 2000–2012."),
("Present and future Köppen-Geiger climate classification maps at 1-km resolution","H. E. Beck et al.",2018,"Scientific Data","10.1038/sdata.2018.214","Climate zones","Open access","CC BY 4.0",True,"https://www.nature.com/articles/sdata2018214.pdf","The standard modern 1-km Köppen map, with projected shifts of climate zones by 2071–2100."),
("Accelerated global glacier mass loss in the early twenty-first century","R. Hugonnet et al.",2021,"Nature","10.1038/s41586-021-03436-z","Glaciers","Subscription","©",False,None,"Glaciers lost ~267 Gt a year in 2000–2019, accelerating, contributing about a fifth of sea-level rise."),
("Community estimate of global glacier mass changes from 2000 to 2023","The GlaMBIE Team",2025,"Nature","10.1038/s41586-024-08545-z","Glaciers","Open access","CC BY 4.0",True,"https://www.nature.com/articles/s41586-024-08545-z.pdf","A reconciled estimate from all methods: glaciers lost about 5% of their ice since 2000, with loss rising by over a third in the second decade."),
("Satellite-based estimates of groundwater depletion in India","M. Rodell, I. Velicogna, J. S. Famiglietti",2009,"Nature","10.1038/nature08238","Groundwater","Subscription","©",False,None,"GRACE gravity data showed Rajasthan, Punjab and Haryana losing ~17.7 km³ of groundwater a year to irrigation."),
("Evolution, consequences and future of plant and animal domestication","J. Diamond",2002,"Nature","10.1038/nature01019","Agriculture origins","Subscription","©",False,None,"Why farming arose in only a few homelands and how it spread and shaped human history."),
("Green Revolution: Impacts, limits, and the path ahead","P. L. Pingali",2012,"PNAS","10.1073/pnas.0912953109","Green Revolution","Open access","PNAS open access",True,"https://www.pnas.org/doi/pdf/10.1073/pnas.0912953109","High-yield varieties averted famine and saved land but left problems of water, soil and nutrition to solve."),
("An assessment of the global impact of 21st century land use change on soil erosion","P. Borrelli et al.",2017,"Nature Communications","10.1038/s41467-017-02142-7","Soil erosion","Open access","CC BY 4.0",True,"https://www.nature.com/articles/s41467-017-02142-7.pdf","Global soil erosion by water was modelled at ~36 billion tonnes a year, rising with cropland expansion."),
("Climate change in the Fertile Crescent and implications of the recent Syrian drought","C. P. Kelley et al.",2015,"PNAS","10.1073/pnas.1421533112","Drought","Open access","PNAS open access",True,"https://www.pnas.org/doi/pdf/10.1073/pnas.1421533112","The 2007–2010 Syrian drought was the worst on record and made 2–3× more likely by human-caused warming."),
("SoilGrids250m: Global gridded soil information based on machine learning","T. Hengl et al.",2017,"PLOS ONE","10.1371/journal.pone.0169748","Soil mapping","Open access","CC BY 4.0",True,"https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0169748&type=printable","Machine learning on ~150,000 soil profiles produced global 250 m maps of soil properties and classes."),
("Climate trends and global crop production since 1980","D. B. Lobell, W. Schlenker, J. Costa-Roberts",2011,"Science","10.1126/science.1204531","Crops & climate","Subscription","©",False,None,"Warming since 1980 cut global maize and wheat yields by several percent compared with a no-warming world."),
("Temperature increase reduces global yields of major crops in four independent estimates","C. Zhao et al.",2017,"PNAS","10.1073/pnas.1701762114","Crops & climate","Open access","PNAS open access",True,"https://www.pnas.org/doi/pdf/10.1073/pnas.1701762114","Each 1°C of warming cuts global yields of maize ~7.4%, wheat ~6.0%, rice ~3.2% and soybean ~3.1%."),
]
out=[]
for n,a,y,j,doi,t,acc,lic,mir,pdf,s in P:
    slug=re.sub(r'[^a-z0-9]+','-',(a.split()[-1] if 'et al' not in a else a.split()[-3]).lower()+f'-{y}-'+' '.join(n.split()[:3]).lower()).strip('-')
    out.append(dict(name=n,authors=a,year=y,journal=j,doi=doi,topic=t,access=acc,license=lic,mirror=mir,pdf_url=pdf,analysis=None,summary=s,slug=slug,url="https://doi.org/"+doi,emoji="📄",group=t))
json.dump(out,open('../papers.json','w'),ensure_ascii=False,indent=1)
print([o['slug'] for o in out])
